public class OrderPayloadParser {
    /**
     * Custom exception for any problem encountered while parsing an order payload.
     * No constructors are declared: Apex custom exceptions inherit the standard
     * Exception constructors (no-arg and String message), so redeclaring them
     * causes "constructor already defined" compile errors.
     */
    public class PayloadException extends Exception {}

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount = 0;
        public Decimal lineTotal;

        public Line() {}
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines = new List<Line>();
        public Decimal total = 0;

        public Order() {}
    }

    /**
     * Parses a JSON order payload into an Order.
     * Throws only PayloadException for any malformed / invalid payload.
     */
    public static Order parse(String body) {
        try {
            return parseInternal(body);
        } catch (PayloadException pe) {
            throw pe;
        } catch (Exception e) {
            // Never leak any other exception type out of parse().
            throw new PayloadException(e.getMessage());
        }
    }

    private static Order parseInternal(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Payload body is null or blank.');
        }

        Object raw;
        try {
            raw = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Payload is not valid JSON: ' + e.getMessage());
        }

        if (!(raw instanceof Map<String, Object>)) {
            throw new PayloadException('Payload must be a JSON object.');
        }

        Map<String, Object> root = (Map<String, Object>) raw;
        Order ord = new Order();

        // number (required, non-blank)
        String orderNumber = asString(root.get('number'));
        if (String.isBlank(orderNumber)) {
            throw new PayloadException('Missing or blank "number".');
        }
        ord.orderNumber = orderNumber;

        // date (ISO yyyy-MM-dd)
        Object dateObj = root.get('date');
        if (dateObj != null) {
            String dateStr = asString(dateObj);
            if (dateStr != null) {
                try {
                    ord.orderDate = Date.valueOf(dateStr);
                } catch (Exception e) {
                    throw new PayloadException('Invalid "date": ' + dateStr);
                }
            }
        }

        // currency
        ord.currencyCode = asString(root.get('currency'));

        // customer.email (customer may be missing)
        Object customerObj = root.get('customer');
        if (customerObj instanceof Map<String, Object>) {
            Map<String, Object> customer = (Map<String, Object>) customerObj;
            ord.customerEmail = asString(customer.get('email'));
        }

        // lines (missing or null -> empty list)
        ord.lines = new List<Line>();
        Object linesObj = root.get('lines');
        if (linesObj != null) {
            if (!(linesObj instanceof List<Object>)) {
                throw new PayloadException('"lines" must be a JSON array.');
            }

            for (Object lineObj : (List<Object>) linesObj) {
                if (!(lineObj instanceof Map<String, Object>)) {
                    throw new PayloadException('Each entry of "lines" must be a JSON object.');
                }
                ord.lines.add(parseLine((Map<String, Object>) lineObj));
            }
        }

        // total = sum of the already-rounded line totals
        Decimal total = 0;
        for (Line line : ord.lines) {
            total += line.lineTotal;
        }
        ord.total = total.setScale(2, System.RoundingMode.HALF_UP);

        return ord;
    }

    private static Line parseLine(Map<String, Object> lineMap) {
        Line line = new Line();

        String sku = asString(lineMap.get('sku'));
        if (String.isBlank(sku)) {
            throw new PayloadException('Line is missing "sku".');
        }
        line.sku = sku;

        Integer quantity = asInteger(lineMap.get('quantity'));
        if (quantity == null || quantity <= 0) {
            throw new PayloadException('Line "quantity" is missing or not positive.');
        }
        line.quantity = quantity;

        Decimal unitPrice = asDecimal(lineMap.get('unitPrice'));
        if (unitPrice == null || unitPrice < 0) {
            throw new PayloadException('Line "unitPrice" is missing or negative.');
        }
        line.unitPrice = unitPrice;

        Decimal discount = asDecimal(lineMap.get('discount'));
        if (discount == null) {
            discount = 0;
        }
        line.discount = discount;

        Decimal gross = (Decimal) quantity * unitPrice;
        Decimal net = gross * (1 - discount);
        line.lineTotal = net.setScale(2, System.RoundingMode.HALF_UP);

        return line;
    }

    /**
     * Builds the acknowledgement JSON: exactly number, status, lineCount, total.
     */
    public static String toAcknowledgement(Order order) {
        if (order == null) {
            throw new PayloadException('Order is null.');
        }

        Integer lineCount = order.lines == null ? 0 : order.lines.size();
        Decimal total = order.total == null ? 0 : order.total;

        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', lineCount);
        ack.put('total', total);

        return JSON.serialize(ack);
    }

    // ---------- helpers ----------

    private static String asString(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof String) {
            return (String) value;
        }
        return String.valueOf(value);
    }

    private static Decimal asDecimal(Object value) {
        if (value == null) {
            return null;
        }
        try {
            if (value instanceof Decimal) {
                return (Decimal) value;
            }
            if (value instanceof Integer) {
                return Decimal.valueOf(String.valueOf(value));
            }
            if (value instanceof Long) {
                return Decimal.valueOf(String.valueOf(value));
            }
            if (value instanceof Double) {
                return Decimal.valueOf((Double) value);
            }
            if (value instanceof String) {
                return Decimal.valueOf((String) value);
            }
        } catch (Exception e) {
            return null;
        }
        return null;
    }

    private static Integer asInteger(Object value) {
        Decimal d = asDecimal(value);
        if (d == null) {
            return null;
        }
        // Reject values that are not whole numbers.
        if (d != d.setScale(0, System.RoundingMode.DOWN)) {
            return null;
        }
        try {
            return d.intValue();
        } catch (Exception e) {
            return null;
        }
    }
}
