/**
 * LogPurgeJob
 *
 * Purges FB_Integration_Log__c records so the log table does not fill up storage.
 *
 * Retention policy
 *  - Records whose Level__c is not 'ERROR' (blank / null included) are deleted once they
 *    were created more than 30 days ago.
 *  - Records whose Level__c is 'ERROR' are kept until they were created more than 180 days ago.
 *
 * The class is Schedulable (so it can run nightly) and Batchable (so the same purge can also
 * be run in bulk with Database.executeBatch(new LogPurgeJob(), 200) when a large backlog has
 * to be cleared in one go).
 *
 * The nightly run deletes the expired rows directly, in chunks, capped at MAX_ROWS_PER_RUN
 * rows per run, so it always stays well inside the synchronous governor limits
 * (50,000 query rows / 10,000 DML rows per transaction). Any remainder is picked up by the
 * following night's run (or by running the class as a batch job).
 */
public class LogPurgeJob implements Schedulable, Database.Batchable<SObject> {

    /** Non-ERROR logs are purged once they are older than this many days. */
    private static final Integer NON_ERROR_RETENTION_DAYS = 30;

    /** ERROR logs are purged once they are older than this many days. */
    private static final Integer ERROR_RETENTION_DAYS = 180;

    /** Number of records deleted per DML statement. */
    private static final Integer DML_CHUNK_SIZE = 200;

    /** Maximum number of records a single nightly (synchronous) run purges. */
    private static final Integer MAX_ROWS_PER_RUN = 9000;

    /** Batch size used when the purge is run as a Batch Apex job. */
    private static final Integer BATCH_SIZE = 200;

    /** Required no-argument constructor. */
    public LogPurgeJob() {
    }

    // ------------------------------------------------------------------
    // Schedulable
    // ------------------------------------------------------------------

    /**
     * Runs the purge. Called by the scheduler every night at 02:00.
     */
    public void execute(SchedulableContext sc) {
        purgeExpiredLogs();
    }

    /**
     * Schedules the nightly purge (every day at 02:00) under the job name 'Log purge (nightly)'.
     *
     * @return the Id returned by System.schedule.
     */
    public static Id scheduleNightly() {
        // Cron expression format: Seconds Minutes Hours Day_of_month Month Day_of_week [Year]
        // '0 0 2 * * ?' -> every day at 02:00:00.
        return System.schedule('Log purge (nightly)', '0 0 2 * * ?', new LogPurgeJob());
    }

    // ------------------------------------------------------------------
    // Batchable (bulk path for very large backlogs)
    // ------------------------------------------------------------------

    public Database.QueryLocator start(Database.BatchableContext bc) {
        return expiredLogs();
    }

    public void execute(Database.BatchableContext bc, List<SObject> scope) {
        // allOrNone = false so a single locked record cannot abort the whole chunk.
        Database.delete(scope, false);
    }

    public void finish(Database.BatchableContext bc) {
        // Nothing to do.
    }

    // ------------------------------------------------------------------
    // Internals
    // ------------------------------------------------------------------

    /**
     * Query locator over every log record that is eligible for deletion.
     */
    private static Database.QueryLocator expiredLogs() {
        DateTime nonErrorCutoff = DateTime.now().addDays(-NON_ERROR_RETENTION_DAYS);
        DateTime errorCutoff    = DateTime.now().addDays(-ERROR_RETENTION_DAYS);

        // A record is expired when it is either
        //  - not ERROR level (blank / null Level__c included) and older than 30 days, or
        //  - ERROR level and older than 180 days.
        // Level__c is a text field that can be blank, so null is matched explicitly:
        // "Level__c != 'ERROR'" on its own never matches a null value.
        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (CreatedDate < :nonErrorCutoff AND (Level__c != 'ERROR' OR Level__c = null))
               OR (CreatedDate < :errorCutoff AND Level__c = 'ERROR')
        ]);
    }

    /**
     * Deletes the expired logs in chunks, capped at MAX_ROWS_PER_RUN records per run so the
     * transaction stays well inside the synchronous governor limits.
     */
    private static void purgeExpiredLogs() {
        Database.QueryLocatorIterator expired = expiredLogs().iterator();
        List<SObject> toDelete = new List<SObject>();
        Integer purged = 0;

        while (expired.hasNext() && purged < MAX_ROWS_PER_RUN) {
            toDelete.add(expired.next());
            purged++;
            if (toDelete.size() == DML_CHUNK_SIZE) {
                Database.delete(toDelete, false);
                toDelete.clear();
            }
        }
        if (!toDelete.isEmpty()) {
            Database.delete(toDelete, false);
        }
    }
}
