/**
 * Selector for the Account SObject.
 *
 * All queries built by this selector:
 *   - return Id, Name and Industry, plus every field in the Account
 *     Credit_Review field set (the field set is resolved at runtime, so
 *     admins can add/remove fields without a code change);
 *   - run in user mode, so the platform enforces the running user's object,
 *     field and sharing access. A user who cannot read one of the selected
 *     fields gets a QueryException instead of data.
 *
 * The user mode / field set behaviour is configured through the selector's
 * data access setting, so it also applies to the no-argument constructor used
 * by the Application selector factory.
 */
public inherited sharing class AccountsSelector extends fflib_SObjectSelector
{
    /**
     * No-argument constructor used by the Application selector factory.
     *
     * includeFieldSetFields = true  -> every query also selects the fields of
     *                                  the field sets returned by
     *                                  getSObjectFieldSetList()
     * enforceCRUD/enforceFLS = false -> not needed, user mode lets the platform
     *                                  enforce object and field access
     * DataAccess.USER_MODE           -> every query is generated with
     *                                  WITH USER_MODE
     */
    public AccountsSelector()
    {
        super(true, false, false, true, fflib_SObjectSelector.DataAccess.USER_MODE);
    }

    public Schema.SObjectType getSObjectType()
    {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList()
    {
        return new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };
    }

    /**
     * Field set(s) added to every query. The members are resolved at runtime,
     * so the Credit_Review field set can be extended by admins without any
     * code change.
     */
    public List<Schema.FieldSet> getSObjectFieldSetList()
    {
        return new List<Schema.FieldSet>{
            Schema.SObjectType.Account.FieldSets.Credit_Review
        };
    }

    /**
     * Selects the accounts with the given Ids.
     */
    public List<Account> selectById(Set<Id> accountIds)
    {
        if (accountIds == null || accountIds.isEmpty())
        {
            return new List<Account>();
        }

        return (List<Account>) Database.query(
            newQueryFactory()
                .setCondition('Id IN :accountIds')
                .toSOQL()
        );
    }

    /**
     * Selects the accounts with the given Ids and their Contacts child records
     * in a single query. The contact subquery is built from ContactsSelector so
     * it uses that selector's field list.
     */
    public List<Account> selectByIdWithContacts(Set<Id> accountIds)
    {
        if (accountIds == null || accountIds.isEmpty())
        {
            return new List<Account>();
        }

        fflib_QueryFactory contactsSubquery = new ContactsSelector().newQueryFactory();

        return (List<Account>) Database.query(
            newQueryFactory()
                .subselectQuery('Contacts', contactsSubquery)
                .setCondition('Id IN :accountIds')
                .toSOQL()
        );
    }
}
