 *   Response : 202 Accepted
 *
 * One HTTP request is sent per Account so that the ERP team can trace every Account on
 * its own. (The ERP API would accept up to 200 customers in one array, but batching them
 * would defeat that traceability requirement.)
 *
 * Why asynchronous: Apex forbids callouts from a trigger, so AccountTrigger only enqueues
 * this Queueable. The class is bulk safe: a transaction may make at most 100 callouts, so
 * the new Accounts are split into chunks of 100 in the trigger's transaction and one job
 * is enqueued per chunk. Each job then sends its own customers and finishes - it never
 * re-enqueues itself, so no chaining (and no recursion) can occur. A marketplace batch of
 * 200 Accounts results in two jobs with 100 requests each.
 */
public with sharing class ErpCustomerSync implements Queueable {

    /** Named Credential endpoint. URL and authentication live in the Named Credential. */
    private static final String ENDPOINT = 'callout:ERP/api/customers';

    /** Content type required by the ERP API. */
    private static final String CONTENT_TYPE = 'application/json';

    /** The ERP answers 202 Accepted for a successfully queued customer. */
    private static final Integer STATUS_ACCEPTED = 202;

    /** Platform limit: callouts allowed per transaction, i.e. customers per job. */
    private static final Integer CALLOUTS_PER_TRANSACTION = 100;

    /** Platform limit: queueable jobs that may be added to the queue per transaction. */
    private static final Integer JOBS_PER_TRANSACTION = 50;

    /** Customers this job is responsible for (at most CALLOUTS_PER_TRANSACTION). */
    private final List<ErpCustomer> customers;

    public ErpCustomerSync(List<ErpCustomer> customers) {
        this.customers = customers;
    }

    /**
     * Entry point called from AccountTrigger (after insert).
     * Splits the new Accounts into chunks of at most 100 and enqueues one job per chunk,
     * so that no transaction ever exceeds the callout limit.
     */
    public static void syncCustomers(List<Account> accounts) {
        if (accounts == null || accounts.isEmpty()) {
            return;
        }

        List<ErpCustomer> customers = new List<ErpCustomer>();
        for (Account account : accounts) {
            customers.add(new ErpCustomer(account));
        }

        List<List<ErpCustomer>> chunks = new List<List<ErpCustomer>>();
        List<ErpCustomer> chunk = new List<ErpCustomer>();
        for (ErpCustomer customer : customers) {
            chunk.add(customer);
            if (chunk.size() == CALLOUTS_PER_TRANSACTION) {
                chunks.add(chunk);
                chunk = new List<ErpCustomer>();
            }
        }
        if (!chunk.isEmpty()) {
            chunks.add(chunk);
        }

        for (Integer i = 0; i < chunks.size(); i++) {
            if (i < JOBS_PER_TRANSACTION) {
                System.enqueueJob(new ErpCustomerSync(chunks[i]));
            } else {
                // Only reachable with more than 5,000 Accounts in a single transaction,
                // which the ticket excludes (marketplace batches are capped at 200).
                System.debug(
                    LoggingLevel.ERROR,
                    'ERP customer sync skipped for ' + chunks[i].size() +
                    ' account(s): more than ' + JOBS_PER_TRANSACTION +
                    ' queueable jobs were needed for a single transaction.'
                );
            }
        }
    }

    /**
     * Sends one request per customer of this job and finishes. This method never
     * enqueues another job, so it cannot recurse.
     */
    public void execute(QueueableContext context) {
        for (ErpCustomer customer : customers) {
            sendCustomer(customer);
        }
    }

    /**
     * One POST with a one element JSON array for a single Account.
     */
    private static void sendCustomer(ErpCustomer customer) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(ENDPOINT);
        request.setMethod('POST');
        request.setHeader('Content-Type', CONTENT_TYPE);
        request.setBody(JSON.serialize(new List<ErpCustomer>{ customer }, false));

        HttpResponse response = new Http().send(request);

        // Error handling and retries are explicitly out of scope for this ticket, so a
        // non-202 answer is only logged. No user is waiting on this job, so throwing here
        // would neither roll back the Account nor help anyone.
        if (response.getStatusCode() != STATUS_ACCEPTED) {
            System.debug(
                LoggingLevel.WARN,
                'ERP rejected account ' + customer.salesforceId + ': HTTP ' +
                response.getStatusCode() + ' ' + response.getStatus()
            );
        }
    }

    /**
     * Payload for a single customer. JSON.serialize(..., false) keeps null values, so a
     * blank BillingCountry is sent as "country": null.
     */
    public class ErpCustomer {
        public String salesforceId; // Account.Id is always the 18 character Id in Apex
        public String name;
        public String country;

        public ErpCustomer(Account account) {
            this.salesforceId = account.Id;
            this.name = account.Name;
            this.country = String.isBlank(account.BillingCountry) ? null : account.BillingCountry;
        }
    }
}
