/**
 * GiftImportService
 *
 * Takes one-off gifts coming from the website and runs them through NPSP's own
 * Data Import engine instead of inserting Contacts/Opportunities directly.
 *
 * For every gift we stage one npsp__DataImport__c record, then invoke NPSP's
 * Apex Data Import API so NPSP applies its configured contact matching,
 * household account creation and donation processing rules (and reads the
 * org's Data Import settings, npsp__Data_Import_Settings__c).  By default that
 * means match contacts on first name, last name and email, and never match
 * existing donations.
 *
 * The staged Data Import records are persisted in the org and remain there as
 * the audit trail of what was imported.
 */
public with sharing class GiftImportService {

    private static final String STATUS_IMPORTED = 'Imported';
    private static final String DONOR_CONTACT1  = 'Contact1';

    /** One-off gift as it arrives from the website. */
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    /** Outcome of importing a single gift. */
    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    /**
     * Stages and processes one NPSP Data Import record per gift, synchronously,
     * in the caller's transaction.  Returns one ImportResult per gift, in the
     * same order as the input.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {

        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // One result object per gift so we can fill them in any order.
        for (Integer i = 0; i < gifts.size(); i++) {
            results.add(new ImportResult());
        }

        // ------------------------------------------------------------------
        // 1. Stage one Data Import record per gift, keeping the input order
        // ------------------------------------------------------------------
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        List<Integer> stagedIndexes = new List<Integer>();

        for (Integer i = 0; i < gifts.size(); i++) {
            WebGift gift = gifts[i];

            if (gift == null) {
                results[i].success = false;
                results[i].errorMessage = 'No gift data was supplied.';
                continue;
            }

            staged.add(new npsp__DataImport__c(
                npsp__Contact1_Firstname__c      = gift.firstName,
                npsp__Contact1_Lastname__c       = gift.lastName,
                npsp__Contact1_Personal_Email__c = gift.email,
                npsp__Donation_Amount__c         = gift.amount,
                npsp__Donation_Date__c           = gift.giftDate,
                npsp__Donation_Donor__c          = DONOR_CONTACT1
            ));
            stagedIndexes.add(i);
        }

        // allOrNone = false so a single malformed row cannot abort the batch.
        List<Database.SaveResult> insertResults = new List<Database.SaveResult>();
        if (!staged.isEmpty()) {
            insertResults = Database.insert(staged, false);
        }

        List<npsp__DataImport__c> toProcess = new List<npsp__DataImport__c>();
        for (Integer j = 0; j < staged.size(); j++) {
            if (insertResults[j].isSuccess()) {
                toProcess.add(staged[j]);
            } else {
                ImportResult result = results[stagedIndexes[j]];
                result.success = false;
                result.errorMessage = joinErrors(insertResults[j].getErrors());
            }
        }

        // ------------------------------------------------------------------
        // 2. Let NPSP import them - synchronously, in this same transaction.
        //    NPSP records a per-row failure on the Data Import record rather
        //    than stopping the rest of the batch.
        // ------------------------------------------------------------------
        String engineError = null;
        if (!toProcess.isEmpty()) {
            try {
                npsp.BDI_DataImport_API.processDataImport(toProcess, false);
            } catch (Exception e) {
                engineError = e.getMessage();
            }
        }

        // ------------------------------------------------------------------
        // 3. Read back what NPSP wrote onto the staged Data Import records.
        // ------------------------------------------------------------------
        Map<Id, npsp__DataImport__c> processed = new Map<Id, npsp__DataImport__c>();
        if (!toProcess.isEmpty()) {
            processed = new Map<Id, npsp__DataImport__c>([
                SELECT Id,
                       npsp__Status__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c,
                       npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :toProcess
            ]);
        }

        // ------------------------------------------------------------------
        // 4. Build one result per gift, in the original input order.
        // ------------------------------------------------------------------
        for (Integer j = 0; j < staged.size(); j++) {

            if (!insertResults[j].isSuccess()) {
                continue; // already populated above
            }

            ImportResult result = results[stagedIndexes[j]];
            npsp__DataImport__c di = processed.get(staged[j].Id);

            if (di == null) {
                // NPSP never wrote a status for this row (e.g. the engine threw).
                result.success = false;
                result.errorMessage = (engineError != null)
                    ? engineError
                    : 'The Data Import record was not processed by NPSP.';
                continue;
            }

            result.success       = (di.npsp__Status__c == STATUS_IMPORTED);
            result.contactId     = di.npsp__Contact1Imported__c;
            result.opportunityId = di.npsp__DonationImported__c;
            result.errorMessage  = result.success ? null : di.npsp__FailureInformation__c;
        }

        return results;
    }

    /** Flattens the Database.Error list of a failed insert into one message. */
    private static String joinErrors(List<Database.Error> errors) {
        List<String> messages = new List<String>();
        if (errors != null) {
            for (Database.Error err : errors) {
                messages.add(err.getMessage());
            }
        }
        return String.join(messages, '; ');
    }
}
