public with sharing class GiftService {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final String ROLE_DONOR = 'Donor';
    private static final String ROLE_HOUSEHOLD_MEMBER = 'Household Member';

    /**
     * Records a gift that has already been received for the supplied contact.
     * The gift is credited to the contact's household account, the contact is the
     * gift's primary contact and holds the Donor role, every other household member
     * holds the Household Member role, and exactly one paid payment covers the full
     * amount on the gift date.
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('A Contact Id is required to record a gift.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('The gift amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('A gift date is required to record a gift.');
        }

        List<Contact> donorRecords = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (donorRecords.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist: ' + contactId);
        }

        Contact donor = donorRecords[0];
        if (donor.AccountId == null) {
            throw new IllegalArgumentException('Contact has no household account: ' + contactId);
        }

        Id householdAccountId = donor.AccountId;

        Set<Id> householdMemberIds = new Set<Id>();
        for (Contact member : [SELECT Id FROM Contact WHERE AccountId = :householdAccountId]) {
            householdMemberIds.add(member.Id);
        }
        householdMemberIds.add(contactId);

        Opportunity gift = new Opportunity(
            Name = buildGiftName(donor, giftDate),
            AccountId = householdAccountId,
            StageName = STAGE_CLOSED_WON,
            CloseDate = giftDate,
            Amount = amount,
            npsp__Primary_Contact__c = contactId
        );
        insert gift;

        syncContactRoles(gift.Id, contactId, householdMemberIds);
        syncPayment(gift.Id, amount, giftDate);
        removeDuplicateContactRoles(gift.Id, contactId, householdMemberIds);
        removeDuplicatePayments(gift.Id);
        syncPrimaryContact(gift.Id, contactId);

        return gift.Id;
    }

    private static String buildGiftName(Contact donor, Date giftDate) {
        String firstName = String.isBlank(donor.FirstName) ? '' : donor.FirstName.trim() + ' ';
        String lastName = String.isBlank(donor.LastName) ? '' : donor.LastName.trim();
        String donorName = (firstName + lastName).trim();
        return donorName + ' Donation ' + String.valueOf(giftDate);
    }

    /**
     * Makes sure every household member has exactly one contact role on the gift:
     * the donor holds Donor (and is the primary role), everyone else holds
     * Household Member. Existing roles are updated in place rather than blindly
     * deleted and re-created, so NPSP automation stays in sync.
     */
    private static void syncContactRoles(Id opportunityId, Id donorContactId, Set<Id> householdMemberIds) {
        List<OpportunityContactRole> existingRoles = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opportunityId
            ORDER BY CreatedDate ASC
        ];

        Map<Id, OpportunityContactRole> roleByContactId = new Map<Id, OpportunityContactRole>();
        List<OpportunityContactRole> rolesToDelete = new List<OpportunityContactRole>();

        for (OpportunityContactRole existingRole : existingRoles) {
            if (roleByContactId.containsKey(existingRole.ContactId)) {
                // Never allow a contact to hold more than one role on the gift.
                rolesToDelete.add(existingRole);
            } else {
                roleByContactId.put(existingRole.ContactId, existingRole);
            }
        }

        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToUpdate = new List<OpportunityContactRole>();

        for (Id memberId : householdMemberIds) {
            Boolean isDonor = (memberId == donorContactId);
            String expectedRole = isDonor ? ROLE_DONOR : ROLE_HOUSEHOLD_MEMBER;
            OpportunityContactRole role = roleByContactId.get(memberId);

            if (role == null) {
                rolesToInsert.add(new OpportunityContactRole(
                    OpportunityId = opportunityId,
                    ContactId = memberId,
                    Role = expectedRole,
                    IsPrimary = isDonor
                ));
            } else if (role.Role != expectedRole || role.IsPrimary != isDonor) {
                role.Role = expectedRole;
                role.IsPrimary = isDonor;
                rolesToUpdate.add(role);
            }
        }

        for (Id contactIdWithRole : roleByContactId.keySet()) {
            if (!householdMemberIds.contains(contactIdWithRole)) {
                rolesToDelete.add(roleByContactId.get(contactIdWithRole));
            }
        }

        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }
        if (!rolesToUpdate.isEmpty()) {
            update rolesToUpdate;
        }
        if (!rolesToDelete.isEmpty()) {
            delete rolesToDelete;
        }
    }

    /**
     * Guarantees exactly one payment on the gift, paid in full on the gift date.
     * NPSP may have already created the payment schedule when the opportunity was
     * inserted, so an existing payment is reused and updated instead of added to.
     */
    private static void syncPayment(Id opportunityId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> payments = [
            SELECT Id, npe01__Paid__c, npe01__Payment_Amount__c, npe01__Payment_Date__c, npe01__Scheduled_Date__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            ORDER BY CreatedDate ASC
        ];

        if (payments.isEmpty()) {
            insert new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
            return;
        }

        npe01__OppPayment__c payment = payments[0];
        payment.npe01__Payment_Amount__c = amount;
        payment.npe01__Payment_Date__c = giftDate;
        payment.npe01__Scheduled_Date__c = giftDate;
        payment.npe01__Paid__c = true;
        update payment;

        if (payments.size() > 1) {
            List<npe01__OppPayment__c> duplicatePayments = new List<npe01__OppPayment__c>();
            for (Integer i = 1; i < payments.size(); i++) {
                duplicatePayments.add(payments[i]);
            }
            delete duplicatePayments;
        }
    }

    /**
     * Safety net: removes any duplicate contact roles that NPSP automation may have
     * created, and re-creates a missing role for a household member.
     */
    private static void removeDuplicateContactRoles(Id opportunityId, Id donorContactId, Set<Id> householdMemberIds) {
        List<OpportunityContactRole> roles = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opportunityId
            ORDER BY CreatedDate ASC
        ];

        Map<Id, OpportunityContactRole> keptRoleByContactId = new Map<Id, OpportunityContactRole>();
        List<OpportunityContactRole> rolesToDelete = new List<OpportunityContactRole>();

        for (OpportunityContactRole role : roles) {
            if (!householdMemberIds.contains(role.ContactId) || keptRoleByContactId.containsKey(role.ContactId)) {
                rolesToDelete.add(role);
            } else {
                keptRoleByContactId.put(role.ContactId, role);
            }
        }

        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();
        for (Id memberId : householdMemberIds) {
            if (!keptRoleByContactId.containsKey(memberId)) {
                Boolean isDonor = (memberId == donorContactId);
                rolesToInsert.add(new OpportunityContactRole(
                    OpportunityId = opportunityId,
                    ContactId = memberId,
                    Role = isDonor ? ROLE_DONOR : ROLE_HOUSEHOLD_MEMBER,
                    IsPrimary = isDonor
                ));
            }
        }

        if (!rolesToDelete.isEmpty()) {
            delete rolesToDelete;
        }
        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }
    }

    /**
     * Safety net: removes any extra payment records, keeping the oldest one.
     */
    private static void removeDuplicatePayments(Id opportunityId) {
        List<npe01__OppPayment__c> payments = [
            SELECT Id
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            ORDER BY CreatedDate ASC
        ];

        if (payments.size() <= 1) {
            return;
        }

        List<npe01__OppPayment__c> duplicatePayments = new List<npe01__OppPayment__c>();
        for (Integer i = 1; i < payments.size(); i++) {
            duplicatePayments.add(payments[i]);
        }
        delete duplicatePayments;
    }

    /**
     * Makes sure the gift's Primary Contact is still the donor, whatever NPSP
     * automation may have done while the contact roles were being maintained.
     */
    private static void syncPrimaryContact(Id opportunityId, Id donorContactId) {
        List<Opportunity> gifts = [
            SELECT Id, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];

        if (gifts.isEmpty()) {
            return;
        }

        if (gifts[0].npsp__Primary_Contact__c != donorContactId) {
            gifts[0].npsp__Primary_Contact__c = donorContactId;
            update gifts[0];
        }
    }
